/* Global Styles */
figure.wp-block-embed-vimeo, figure.wp-block-embed-youtube {
	max-width: 800px;
}

body {
	margin: 0px auto;
}
main, footer {
	max-width: 1490px;
	margin: 0 auto;
}
h1.wp-block-post-title {
	font-size: 40px;
	font-weight: 600;
	font-family: 'Libre Baskerville'!important;
}
.orange-border-header {
	border-left: 5px solid #ffa300;
}
.blue-border-header {
	border-left: 5px solid #00629b;
}
p {
	font-size: 18px;
	color: #000;
}
.wp-block-post-template .wp-block-post-title a, .ultp-block-items-wrap .ultp-block-item .ultp-block-title a {
	font-family: 'Libre Baskerville'!important;
}
.ultp-block-items-wrap .ultp-block-item .ultp-block-title a {
	font-family: 'Libre Baskerville'!important;
	font-weight: 600!important;
}
a, a:link, a:visited, a:active, .wp-block-post-template .wp-block-post-title a, .wp-block-post-template .wp-block-post-title h2 a {
	color: #00629B;
	text-decoration: underline!important;
}
a:hover, .ultp-block-items-wrap .ultp-block-item .ultp-category-grid a, .wp-block-post-template .wp-block-post-title a:hover {
	color: #68a0c1!important;
	text-decoration: underline!important;
}
h1.has-background {
	padding: 10px 20px;
}
.header-media-inner-post.without-bg {
	margin-top: 0!important;
	padding: 0;
	padding-top: 0!important;
}
body:not(.home) .wp-site-blocks main {
	padding-top: 0!important;
}
.wp-block-post-template > li {
	border-bottom: 1px solid #63666A;
}
.divider-line {
    height: 3px;
    background: linear-gradient(to right, #00629b 0%, #00629b 42%, #ffa300 42%, #ffa300 60%, #41b6e6 60%, #41b6e6 100%);
}
.header-divider-line {
    height: 3px;
    background: linear-gradient(to right, #00629b 0%, #00629b 42%, #ffa300 42%, #ffa300 60%, #41b6e6 60%, #41b6e6 100%);
}

/* Search Styles */
.taxonomy-category a {
	color: #00629B!important;
	text-decoration: underline!important;
}
.taxonomy-category a:hover {
	color: #68a0c1!important;
	text-decoration: underline!important;
}
.is-form-style input.is-search-submit {
	border-radius: 0!important;
}

/* Header Styles */
.mobile-header {
	display: none;
	background-color: white;
}
header {
	width: 100%; 
	position: sticky; 
	top: 0; 
	/*left: 0; */
	z-index: 10; 
	background-color: white; 
	max-width: 1490px;
	margin: 0 auto;
}
.header-logo {
	transition: max-width 400ms;
	max-width: 400px;
}
.header-logo img {
	margin-right: 0;
}
.desktop-header .scrolled {
	max-width: 250px;
}
.mobile-header .header-logo img {
	max-width: 250px;
}
/* Header logo: keep aspect ratio when it shrinks */
.header-logo img {
	height: auto !important;
}

/* Mobile: let the logo fit its column instead of overlapping the nav */
.mobile-header .header-logo img {
	max-width: 100%;
}
.mobile-header .impact-header {
	margin-right: 0;
	margin-left: 0;
}
.mobile-header .right-side-header {
	width: 50%;
	margin-right: -20px;
}
.mobile-header .left-side-header {
	width: 70%;
	margin-left: -20px;
}
body .is-layout-flex {
	gap: 15px;
}
#gtranslate_selector {
	cursor: pointer;
	font-family: 'Montserrat';
	font-size: 16px;
	padding: 5px 0 5px 5px;
	font-weight: 500;
}
.disclaimer-popup, .disclaimer-popup-mobile {
	position: relative;
	display: inline-block;
	cursor: pointer;
	-webkit-user-select: none;
	-moz-user-select: none;
	-ms-user-select: none;
	user-select: none;
	color: #00629b;
}
.disclaimer-popup:hover, .disclaimer-popup-mobile:hover {
	color: #68a0c1;
}
.disclaimer-popup .popup-text, .disclaimer-popup-mobile .popup-text {
	display: none;
	width: 300px;
	background-color: #f6f6f6;
	color: #000000;
	text-align: left;
	border-radius: 5px;
	padding: 15px;
	position: absolute;
	z-index: 1;
	top: 110%;
	right: 0;
	font-size: 12px;
}

#mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-item > a.mega-menu-link, #mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-item > a.mega-menu-link:focus, #mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-item > a.mega-menu-link:visited {
	color: #00629b!important;
	font-family: 'Montserrat';
	font-size: 22px;
	font-weight: 600!important;
}
#mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-item > a.mega-menu-link:hover {
	color: #68a0c1;
	font-size: 22px;
	font-weight: 600;
}
#mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 li.mega-menu-item-has-children > a.mega-menu-link > span.mega-indicator {
	margin: 0;
}
#mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-flyout ul.mega-sub-menu {
	font-family: 'Montserrat';
	padding: 10px!important;
	width: 155px;
	font-weight: 500;
	position: absolute;
	box-shadow: 2px 3px 5px rgba(0,0,0,0.2);
}
.header-search {
	display: inline-block;
	top: 10px;
}
.header-search svg {
	display: inline-block;
	width: 25px;
	height: 25px;
}
.is-form-style input.is-search-submit, .is-search-icon {
	font-size: 16px!important;
}

/* Footer Styles */
.copyright a {
	color: #fff;
}
.copyright a:hover, .mega-sub-menu a.mega-menu-link:hover {
	color: #D5D5DA!important;
}
.wp-block-footer-widget-area-columns {
	padding-top: 0!important;
	padding-bottom: 0!important;
}
.stacked-logo {
	position: relative;
}
a.dfcilogo {
    display: block;
    width: 100%;
    position: absolute;
    top: 0px;
    right: 0px;
    bottom: 0px;
    height: 50%;
}
a.jflogo {
    display: block;
    width:100%;
    position: absolute;
    top: auto;
    right: 0px;
    bottom: 0px;
    height: 50%;
}

/* Homepage */
.homepage-banner .wp-block-cover__inner-container h1 {
	position: absolute;
	top: 80%;
	left: 0;
}
.stk-block-posts__item {
	background-color: #f6f6f6;
}
.stk-block-posts__items .stk-container {
	margin: 0;
}
.stk-block-posts__category.stk-subtitle, .stk-block-posts__title {
	padding: 0 40px;
}
.homepage-banner-button a:hover, .in-brief-button a:hover {
	background-color: #fff!important;
}
.stk-block-posts__title {
	padding-bottom: 15px;
}
/* Issue Page Styles */
.issue-page-header {
	width: 495px;
	float: right;
	margin-top: 18%;
}
.homepage-header h1, .issue-page-header h1 {
	background-color: rgb(0, 98, 155, .5);
	padding: 10px;
}
.ultp-pagination-wrap .ultp-pagination li a {
	text-decoration: none!important;
}
.issue-page-banner .ultp-heading-wrap .ultp-heading-inner {
	margin-top: 250px;
  margin-left: 0;
}
.ultp-pagination-wrap .ultp-pagination li a:hover {
	color: #fff;
}

/* Post Page Styles */
p.has-drop-cap:not(:focus):first-letter {
	color: #41b6e6;
	font-size: 90px;
}
.wp-block-image figcaption, .wp-element-caption {
	color: #000000 !important;
	opacity: 1 !important; 
	text-align: left !important;
	margin-bottom: 10px;
	font-size: 14px!important;
}
.no-caption-image {
	padding-bottom: 15px;
}
.wp-block-gallery.has-nested-images figure.wp-block-image figcaption {
	color: #ffffff !important;
	background: linear-gradient(0deg,rgba(0,0,0,.7),rgba(0,0,0,.3) 80%,transparent);
}
h2.story-h2 {
	padding-top: 25px;
	font-size: 28px;
	color: #003354;
}
h2.story-h2:first-of-type {
	padding-top: 0px;
}
.single .taxonomy-category.wp-block-post-terms > a, .single .taxonomy-post_tag.wp-block-post-terms > a {
	border: none!important;
	text-transform: none!important;
}

.single .taxonomy-category.wp-block-post-terms > a:hover, .single .taxonomy-post_tag.wp-block-post-terms > a:hover {
	background: none!important;
}

/* Left Border Quote */
.wp-block-quote {
	border-left: 3px solid #ffa300;	
	margin-top: 30px;
}
.wp-block-quote p {
	color: #003354;
	font-size: 22px;
	font-style: normal;
	font-weight: 600;
	font-family: 'Montserrat';
}
.wp-block-quote cite {
	font-weight: 500;
	color: #003354;
	opacity: initial;
}

/* Top/Bottom Border Quote */
.wp-block-pullquote {
	padding: 10px;
	text-align: left;
	width: 48%;
	float: left;
	margin-right: 40px;
	margin-bottom: 20px!important;
	border-top-color: #ffa300;
	border-top-width: 3px;
	border-right-style: none;
	border-right-width: 0px;
	border-bottom-color: #ffa300;
	border-bottom-width: 3px;
	border-left-style: none;
	border-left-width: 0px;
	color: #003354;
	font-size: 22px;
	font-style: normal;
	font-weight: 600;
	font-family: 'Montserrat';
}
.wp-block-pullquote p {
	font-size: 22px;
}
.wp-block-pullquote cite {
	color: #003354;
	font-weight: 500;
	opacity: initial;
}
.single .taxonomy-category.wp-block-post-terms > a, .single .taxonomy-post_tag.wp-block-post-terms > a {
	text-transform: none;
	border: none;
	font-size: 18px;
	padding: 0;
	margin-right: 20px;
}
.single .taxonomy-category.wp-block-post-terms > a:hover, .single .taxonomy-post_tag.wp-block-post-terms > a:hover, .single .taxonomy-category.wp-block-post-terms > a:focus, .single .taxonomy-post_tag.wp-block-post-terms > a:focus {
	text-transform: none;
	border: none;
	background-color: transparent;
}
.ss-inline-share-wrapper {
	padding-top: 20px;
}
.jp-related-posts-i2__post {
	margin: 0;
}
.jp-related-posts-i2__post-link, .jp-related-posts-i2__post-link a {
	font-weight: 500;
	font-family: 'Libre Baskerville'!important;
	font-size: 20px;
}
.wp-block-jetpack-related-posts img {
	height: auto !important;
}

/* Archive Template Styles */
.wp-block-post-excerpt__more-link {
	background-color: transparent!important;
	color: #00629b!important;
	font-weight: 500!important;
	text-transform: none!important;
	padding: 0!important;
	font-size: 16px!important;
}
.wp-block-post-excerpt__more-link:hover {
	color: #68a0c1!important;
}
.wp-block-post-template > li {
	margin-bottom: 30px;
	padding-bottom: 30px;
}
a.wp-block-query-pagination-next, a.wp-block-query-pagination-next:focus, a.wp-block-query-pagination-previous, a.wp-block-query-pagination-previous:focus {
	color: #fff!important;
	background-color: #00629b;
	border: 2px solid #00629b;
	border-radius: 5px;
	text-decoration: none!important;
}
a.wp-block-query-pagination-next:hover, a.wp-block-query-pagination-previous:hover {
	color: #00629b!important;
	background-color: transparent;
	border: 2px solid #00629b;
	border-radius: 5px;
}
.wp-block-query-pagination-numbers .page-numbers, .wp-block-query-pagination-numbers .page-numbers:focus {
	text-decoration: none!important;
	background-color: #00629b!important;
	border: 2px solid #00629b!important;
	color: #fff!important;
}
.wp-block-query-pagination-numbers .page-numbers:hover, .wp-block-query-pagination-numbers .page-numbers.current {
	text-decoration: none!important;
	background-color: transparent!important;
	border: 2px solid #00629b;
	color: #00629b!important;
}

/* Button Block Styles */
a.wp-block-button__link {
	text-decoration: none!important;
}
.wp-block-button__link {
	border: 2px solid #00629B;
}
.wp-block-button__link:hover {
	background-color: transparent!important;
	color: #00629B!important;
	border: 2px solid #00629B!important;
}

/* Issue Page Styles */
figure.issue-cover {
	box-shadow: 2px 2px 7px #ccc;
	margin-bottom: 10px;
}

/* Mobile Styles */
@media only screen and (max-width: 1590px) {
.homepage-banner .wp-block-cover__inner-container h1 {
	top: 68%;
}
}
@media only screen and (max-width: 1050px) {
.homepage-banner .wp-block-cover__inner-container h1 {
	font-size: 55px!important;
}
body .is-layout-flow > .alignright:first-of-type {
		float: none;
    margin-left: 0;
	}
}
@media only screen and (max-width: 860px) {
h1.wp-block-post-title {
	font-size: 28px!important;
}
.homepage-banner .wp-block-cover__inner-container h1 {
	font-size: 45px!important;
}
.df-header-logo, .jf-header-logo, .wp-block-spacer {
	display: none;
} 
#mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-item {
	display: inline-block;
}
.jp-related-posts-i2__row {
	display: block;
}
.jp-related-posts-i2__post {
	max-width: none!important;
	margin-top: 30px;
}
}
@media only screen and (max-width: 768px) {
.mobile-header {
	display: block;
}
.desktop-header {
	display: none;
}
.blue-border-header {
	font-size: 28px!important;
}
.homepage-banner {
	min-height: 400px!important;
}
.homepage-banner .wp-block-cover__inner-container h1 {
	font-size: 34px!important;
	top: 60%;
}
.issue-page-header {
	width: inherit;
	float: none;
	margin: 0 auto;
}
.wp-block-query-pagination.is-content-justification-space-between>.wp-block-query-pagination-next:last-child {
	margin-inline-start: initial;
}
#mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-item {
	  display: inline-block!important;
	}
#mega-menu-wrap-max_mega_menu_1 #mega-menu-max_mega_menu_1 > li.mega-menu-item > a.mega-menu-link {
		font-size: 22px!important;
	}
}

@media only screen and (max-width: 650px) {
body .is-layout-flow > .alignright, body .is-layout-flow > .alignleft {
	float: none;
	margin-left: 0;
}
.tiled-gallery__gallery, p.gallery-caption {
	display: none;
}
.wp-block-pullquote {
	width: initial;
	float: none;
}
.jp-related-posts-i2__post-img-link img {
	width: 92%;
}
.wp-block-gallery.has-nested-images figure.wp-block-image:not(#individual-image) {
    width: initial;
}
}
@media only screen and (max-width: 480px) {
.main-header-section {
	display: inline-block!important;
}
.mobile-header .left-side-header {
